mapper.select:
select count(1)
from `ry_rental`.`ry_rental_brand_model`
where class_id = #{classId}
  and brand = #{brand}
  and model_name = #{modelName}
  and coalesce(memory_spec, '') = coalesce(#{memorySpec}, '')
  and is_delete = 0
and model_id != #{excludeModelId}

mapper.insert:
insert into `ry_rental`.`ry_rental_brand_model`(
    class_id, brand, model_name, memory_spec, official_flag, status,
    is_delete, create_by, create_time, remark
) values (
    #{classId}, #{brand}, #{modelName}, #{memorySpec}, #{officialFlag}, #{status},
    0, #{createBy}, sysdate(), #{remark}
)
